            .tabItem { Label("Profile", systemImage: "person.crop.circle") }
            .tag(Tab.profile)
        }
        .tint(.teal)
    }

    private enum Tab: Hashable {
        case overview
        case portfolio
        case activity
        case profile
    }
}

